mapper.select:
SELECT user.uid,
       username,
       authority,
       cno,
       email,
       cname,
       csex,
       cage,
       caddress,
       cphone,
       cdate,
       cremark,
       balance
FROM user, client

    user.uid = client.uid

        and CAST(user.uid AS CHAR) = #{uid}


        and CAST(user.uid AS CHAR) like concat('%', #{uid}, '%')


        and BINARY username = #{username}


        and username like concat('%', #{username}, '%')


        and BINARY email = #{email}


        and email like concat('%', #{email}, '%')


        and authority = #{authority}


        and authority like concat('%', #{authority}, '%')


        and BINARY cno = #{cno}


        and cno like concat('%', #{cno}, '%')


        and BINARY cname = #{cname}


        and cname like concat('%', #{cname}, '%')


        and csex = #{csex}


        and csex like concat('%', #{csex}, '%')


        and cage = #{cage}


        and cage like concat('%', #{cage}, '%')


        and BINARY caddress = #{caddress}


        and caddress like concat('%', #{caddress}, '%')


        and BINARY cphone = #{cphone}


        and cphone like concat('%', #{cphone}, '%')


        and cdate between #{startDate} and #{endDate}


        and BINARY cremark = #{cremark}


        and cremark like concat('%', #{cremark}, '%')


        and balance = #{balance}


        and balance like concat('%', #{balance}, '%')


ORDER BY user.authority ASC, user.uid ASC

